 private int checks;private final StringBuilder output=new StringBuilder();private Context c;private volatile Intent result;private volatile CountDownLatch latch;private File fixture;private FileStore store;private Uri initial,outside;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String label){checks++;output.append(ok?"PASS ":"FAIL ").append(label).append('\n');if(!ok)throw new AssertionError(label);}
 private void main(Runnable run){Throwable[] fail={null};runOnMainSync(()->{try{run.run();}catch(Throwable e){fail[0]=e;}});waitForIdleSync();if(fail[0]!=null)throw new AssertionError(fail[0]);}
 private Object field(Object a,String name)throws Exception {Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private String shell(String command)throws Exception {try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor());ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buf=new byte[2048];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);return new String(bytes.toByteArray(),"UTF-8");}}
 private void write(File file,String text)throws Exception {try(OutputStream out=new FileOutputStream(file)){out.write(text.getBytes("UTF-8"));}}
 private String read(File file)throws Exception {try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[1000];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}
 @SuppressWarnings("unchecked")private List<FileStore.Node> entries(FileActivity a)throws Exception {return (List<FileStore.Node>)field(a,"entries");}
 private void loaded(FileActivity a)throws Exception {long deadline=System.currentTimeMillis()+20000;while(entries(a).isEmpty()&&System.currentTimeMillis()<deadline){Thread.sleep(80);waitForIdleSync();}check(!entries(a).isEmpty(),"picker loaded fixture list");}
 private View rowControl(FileActivity a,String name,int child)throws Exception {ListView list=(ListView)field(a,"list");for(int i=0;i<entries(a).size();i++)if(entries(a).get(i).file.getName().equals(name))return ((ViewGroup)list.getAdapter().getView(i+list.getHeaderViewsCount(),null,list)).getChildAt(child);throw new AssertionError("No row "+name);}
 private FileActivity startClient(String action,String mime,boolean multiple)throws Exception {shell("am force-stop ru.truetv.probe");result=null;latch=new CountDownLatch(1);ActivityMonitor monitor=new ActivityMonitor(FileActivity.class.getName(),null,false);addMonitor(monitor);Intent start=new Intent().setComponent(new ComponentName("ru.truetv.probe","ru.truetv.probe.FileClient")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("action",action).putExtra("initial",initial.toString()).putExtra("multiple",multiple).putExtra("outside",outside.toString());if(mime!=null)start.putExtra("mime",mime);c.startActivity(start);FileActivity a=(FileActivity)waitForMonitorWithTimeout(monitor,40000);removeMonitor(monitor);check(a!=null,"implicit "+action+" resolves without DocumentsUI");loaded(a);return a;}
 private Intent await()throws Exception {check(latch.await(20,TimeUnit.SECONDS),"external client returned result");check(result.getBooleanExtra("ok",false),"external client actually read URI: "+result.getStringExtra("error"));return result;}
 private void select(FileActivity a,String name)throws Exception {View view=rowControl(a,name,0);main(view::performClick);}
 private String focusedName(FileActivity value)throws Exception {ListView list=(ListView)field(value,"list");long deadline=System.currentTimeMillis()+3000;while(System.currentTimeMillis()<deadline){waitForIdleSync();for(int i=0;i<list.getChildCount();i++)if(list.getChildAt(i).hasFocus()){int raw=list.getFirstVisiblePosition()+i-list.getHeaderViewsCount();return raw>=0&&raw<entries(value).size()?entries(value).get(raw).file.getName():"@parent";}Thread.sleep(60);}return "";}
 private void remoteKey(int key)throws Exception {VmWindows.ready(this);sendKeyDownUpSync(key);waitForIdleSync();}
 private void remoteEvent(KeyEvent event)throws Exception {VmWindows.ready(this);sendKeySync(event);}
 private Object fieldSafe(Object value,String name){try{return field(value,name);}catch(Exception e){throw new AssertionError(e);}}
 private void invoke(Object value,String name){invoke(value,name,new Class<?>[0],new Object[0]);}
 private void invoke(Object value,String name,Class<?>[] types,Object[] args){try{Method m=value.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(value,args);}catch(Exception e){throw new AssertionError(e);}}
 private ActionSheet showMenu(FileActivity a,String name)throws Exception {main(rowControl(a,name,0)::performLongClick);Field active=ActionSheet.class.getDeclaredField("active");active.setAccessible(true);ActionSheet sheet=(ActionSheet)((java.lang.ref.WeakReference<?>)active.get(null)).get();check(sheet!=null&&sheet.dialog.isShowing(),"long OK opens real context menu for "+name);return sheet;}
 @SuppressWarnings("unchecked")private List<ActionSheet.Item> choices(ActionSheet sheet)throws Exception {return (List<ActionSheet.Item>)field(sheet,"items");}
 private String titles(ActionSheet sheet)throws Exception {StringBuilder text=new StringBuilder();for(ActionSheet.Item i:choices(sheet))text.append(i.title).append('\n');return text.toString();}
 private void choose(ActionSheet sheet,String label)throws Exception {List<ActionSheet.Item> items=choices(sheet);for(int i=0;i<items.size();i++)if(items.get(i).title.equals(label)){View view=sheet.rows.get(i);main(view::performClick);return;}throw new AssertionError("Missing item: "+label+" in "+titles(sheet));}
